-- Recusas da carga (fase 2, K2, C7): catálogo do produto dos parâmetros que a importação usa para continuar a
-- configuração do hospital (ADR 0006; listas do hospital em parametro_opcao, valores em parametro_valor). Sem a
-- definição, a carga recusava as opções e os valores (respostas padrão dos formulários e cerca de 20 configurações
-- pequenas). GERADA de packages/contratos/src/parametros/continuidade.ts (chave, tipo, descrição, padrão, mínimo,
-- máximo e área dona iguais; conferido por continuidade.spec.ts): não editar à mão.
-- Idempotente e válida em qualquer ordem (ADR 0002): inclui a definição que falta e acerta a que esta mesma semente
-- gravou antes (fundamento da continuidade); a definição de outra origem e os valores do cliente não são tocados.

INSERT INTO modulo_sistema (codigo, descricao, ativo, ordem, criado_em)
  SELECT 'agenda', 'Agenda', TRUE, 0, UTC_TIMESTAMP(3) FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM modulo_sistema WHERE codigo = 'agenda');
INSERT INTO modulo_sistema (codigo, descricao, ativo, ordem, criado_em)
  SELECT 'financeiro', 'Financeiro', TRUE, 0, UTC_TIMESTAMP(3) FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM modulo_sistema WHERE codigo = 'financeiro');
INSERT INTO modulo_sistema (codigo, descricao, ativo, ordem, criado_em)
  SELECT 'hotelaria', 'Hotelaria', TRUE, 0, UTC_TIMESTAMP(3) FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM modulo_sistema WHERE codigo = 'hotelaria');
INSERT INTO modulo_sistema (codigo, descricao, ativo, ordem, criado_em)
  SELECT 'pep', 'Prontuário eletrônico', TRUE, 0, UTC_TIMESTAMP(3) FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM modulo_sistema WHERE codigo = 'pep');
INSERT INTO modulo_sistema (codigo, descricao, ativo, ordem, criado_em)
  SELECT 'sadt', 'Apoio diagnóstico e terapêutico', TRUE, 0, UTC_TIMESTAMP(3) FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM modulo_sistema WHERE codigo = 'sadt');
DROP TEMPORARY TABLE IF EXISTS tmp_parametro_continuidade;
CREATE TEMPORARY TABLE tmp_parametro_continuidade AS
  SELECT * FROM (
    SELECT 'agenda.cadeira.agendamentoAutomaticoPlanejamento' AS chave, 'agenda' AS modulo, 'Agendamento automático pelo planejamento' AS descricao, 'booleano' AS tipo, 'false' AS valor_padrao, NULL AS minimo, NULL AS maximo, 'agenda' AS area_dona, NULL AS formato_expressao, TRUE AS permite_rede, TRUE AS permite_estabelecimento
    UNION ALL SELECT 'agenda.cadeira.agendamentoPendenteAnterior' AS chave, 'agenda' AS modulo, 'Agendamento pendente do cadastro anterior (id)' AS descricao, 'inteiro' AS tipo, '0' AS valor_padrao, 0 AS minimo, NULL AS maximo, 'agenda' AS area_dona, NULL AS formato_expressao, TRUE AS permite_rede, TRUE AS permite_estabelecimento
    UNION ALL SELECT 'agenda.cadeira.canalGeracaoPlanejamento' AS chave, 'agenda' AS modulo, 'Canal da marcação gerada pelo planejamento (id)' AS descricao, 'inteiro' AS tipo, '0' AS valor_padrao, 0 AS minimo, NULL AS maximo, 'agenda' AS area_dona, NULL AS formato_expressao, TRUE AS permite_rede, TRUE AS permite_estabelecimento
    UNION ALL SELECT 'agenda.cadeira.digitarEnfermeiroResponsavel' AS chave, 'agenda' AS modulo, 'Digitar o enfermeiro responsável' AS descricao, 'booleano' AS tipo, 'false' AS valor_padrao, NULL AS minimo, NULL AS maximo, 'agenda' AS area_dona, NULL AS formato_expressao, TRUE AS permite_rede, TRUE AS permite_estabelecimento
    UNION ALL SELECT 'agenda.cadeira.duracaoCurta' AS chave, 'agenda' AS modulo, 'Duração da sessão curta (minutos)' AS descricao, 'inteiro' AS tipo, '0' AS valor_padrao, 0 AS minimo, NULL AS maximo, 'agenda' AS area_dona, NULL AS formato_expressao, TRUE AS permite_rede, TRUE AS permite_estabelecimento
