INSERT INTO parametro_definicao (chave, modulo_sistema_id, descricao, tipo, valor_padrao, permite_rede,
  permite_estabelecimento, minimo, maximo, area_dona, formato_expressao, fundamento, ativo, criado_em)
  SELECT x.chave, (SELECT MIN(m.id) FROM modulo_sistema m WHERE m.codigo = x.modulo), x.descricao, x.tipo, x.valor_padrao,
    x.permite_rede, x.permite_estabelecimento, x.minimo, x.maximo, x.area_dona, x.formato_expressao, 'Continuidade do hospital migrado (ADR 0006)', TRUE, UTC_TIMESTAMP(3)
  FROM tmp_parametro_continuidade x
  WHERE NOT EXISTS (SELECT 1 FROM parametro_definicao d WHERE d.chave = x.chave);
UPDATE parametro_definicao d JOIN tmp_parametro_continuidade x ON x.chave = d.chave
  SET d.descricao = x.descricao, d.tipo = x.tipo, d.valor_padrao = x.valor_padrao, d.minimo = x.minimo,
    d.maximo = x.maximo, d.area_dona = x.area_dona, d.formato_expressao = x.formato_expressao, d.alterado_em = UTC_TIMESTAMP(3)
  WHERE d.fundamento = 'Continuidade do hospital migrado (ADR 0006)'
    AND NOT (d.descricao <=> x.descricao AND d.tipo <=> x.tipo AND d.valor_padrao <=> x.valor_padrao
             AND d.minimo <=> x.minimo AND d.maximo <=> x.maximo AND d.area_dona <=> x.area_dona
             AND d.formato_expressao <=> x.formato_expressao);
DROP TEMPORARY TABLE tmp_parametro_continuidade;
